const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions - Mount Stanley, Rwenzori Mountains
  const mountStanley = ee.Geometry.Point([29.8717, 0.3854]).buffer(3000); // 3km buffer around peak

  const date2020Start = '2020-01-01';
  const date2020End = '2020-12-31';
  const date2024Start = '2024-01-01';
  const date2024End = '2024-12-31';

  // 2. Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                   .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to add NDSI
  function addNDSI(image) {
    const ndsi = image.normalizedDifference(['B3', 'B11']).rename('NDSI');
    return image.addBands(ndsi);
  }

  // 3. Data Acquisition for 2020
  let col2020 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(mountStanley)
    .filterDate(date2020Start, date2020End)
    .map(maskS2clouds)
    .map(addNDSI);

  const size2020 = col2020.size().getInfo();
  console.log(`2020 Images found: ${size2020}`);

  if (size2020 === 0) {
    console.log('No Sentinel-2 data for 2020, trying Landsat 8...');
    col2020 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(mountStanley)
      .filterDate(date2020Start, date2020End)
      .map(function(img) {
        const ndsi = img.normalizedDifference(['SR_B3', 'SR_B6']).rename('NDSI');
        return img.addBands(ndsi);
      });
    const size2020L8 = col2020.size().getInfo();
    console.log(`2020 Landsat 8 Images found: ${size2020L8}`);
    if (size2020L8 === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 4. Data Acquisition for 2024
  let col2024 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(mountStanley)
    .filterDate(date2024Start, date2024End)
    .map(maskS2clouds)
    .map(addNDSI);

  const size2024 = col2024.size().getInfo();
  console.log(`2024 Images found: ${size2024}`);

  if (size2024 === 0) {
    console.log('No Sentinel-2 data for 2024, trying Landsat 9...');
    col2024 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
      .filterBounds(mountStanley)
      .filterDate(date2024Start, date2024End)
      .map(function(img) {
        const ndsi = img.normalizedDifference(['SR_B3', 'SR_B6']).rename('NDSI');
        return img.addBands(ndsi);
      });
    const size2024L9 = col2024.size().getInfo();
    console.log(`2024 Landsat 9 Images found: ${size2024L9}`);
    if (size2024L9 === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 5. Calculate snow/ice cover (NDSI > 0.4)
  const snowMask2020 = col2020.select('NDSI').median().gt(0.4);
  const snowMask2024 = col2024.select('NDSI').median().gt(0.4);

  // 6. Calculate pixel counts
  const stats2020 = snowMask2020.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: mountStanley,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2024 = snowMask2024.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: mountStanley,
    scale: 1000,
    maxPixels: 1e9
  });

  const snowPixels2020 = stats2020.get('NDSI').getInfo();
  const snowPixels2024 = stats2024.get('NDSI').getInfo();

  console.log(`Snow/ice pixels 2020: ${snowPixels2020}`);
  console.log(`Snow/ice pixels 2024: ${snowPixels2024}`);

  // 7. Validation & Final Answer
  if (snowPixels2020 === null || snowPixels2024 === null) {
    console.log('<answer>C3</answer>');
    return;
  }

  if (snowPixels2020 === 0 && snowPixels2024 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  const percentChange = ((snowPixels2020 - snowPixels2024) / snowPixels2020 * 100);
  console.log(`Change: ${percentChange.toFixed(2)}%`);

  if (snowPixels2024 < snowPixels2020) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
